"""The two supported playstyles, embedded so script-only updates are complete."""

BUILT_IN_PLAYSTYLES = {'aggressive.xlambot': '{"name": "Aggressive", "description": "Активно ищет бой и давит ближайших противников.", "brawlers": ["all"], "gamemodes": ["all"], "author": "xlamBOT", "date": "2026-10-06"}\n\n# ═══════════════════════════════════════════════════════\n#  SETUP\n# ═══════════════════════════════════════════════════════\n\n_brawler_name = brawler or current_brawler\nbrawler_info = brawlers_info.get(_brawler_name)\n\nif not brawler_info:\n    raise ValueError(f"Brawler \'{_brawler_name}\' not found in brawlers_info.")\n\npersistent_data.setdefault("time_since_holding_attack", None)\npersistent_data.setdefault("last_gadget_use", 0.0)\n\nmust_hold = must_brawler_hold_attack(_brawler_name, brawlers_info)\n\nsafe_range, attack_range, super_range = get_brawler_range(_brawler_name)\nplayer_pos = get_entity_pos(player_data)\n\nmovement = (0, 0)\n\n\n# ═══════════════════════════════════════════════════════\n#  VECTOR / MOVEMENT HELPERS\n# ═══════════════════════════════════════════════════════\n\ndef vec_len(x, y):\n    return math.sqrt(x * x + y * y)\n\ndef normalize_move(x, y, radius=JOYSTICK_RADIUS):\n    length = vec_len(x, y)\n    if length <= 0:\n        return (0, 0)\n    scale = radius / length\n    return (x * scale, y * scale)\n\ndef is_blocked(move):\n    return is_path_blocked(player_data, move, walls)\n\ndef first_unblocked(moves, fallback=None):\n    for move in moves:\n        if not is_blocked(move):\n            return move\n    if fallback is not None:\n        return fallback\n    if moves:\n        return moves[0]\n    return (0, 0)\n\ndef move_toward(target_pos):\n    dx = target_pos[0] - player_pos[0]\n    dy = target_pos[1] - player_pos[1]\n    full = normalize_move(dx, dy)\n    x_only = normalize_move(dx, 0)\n    y_only = normalize_move(0, dy)\n    return first_unblocked([full, x_only, y_only], full)\n\ndef move_away_from(target_pos):\n    dx = player_pos[0] - target_pos[0]\n    dy = player_pos[1] - target_pos[1]\n    full = normalize_move(dx, dy)\n    x_only = normalize_move(dx, 0)\n    y_only = normalize_move(0, dy)\n    return first_unblocked([full, x_only, y_only], full)\n\ndef strafe_around(target_pos):\n    dx = target_pos[0] - player_pos[0]\n    dy = target_pos[1] - player_pos[1]\n    side = 1 if int(time.time() / 2) % 2 == 0 else -1\n    sx = -dy * side\n    sy = dx * side\n    full = normalize_move(sx, sy)\n    reverse = normalize_move(-sx, -sy)\n    return first_unblocked([full, reverse], full)\n\ndef random_safe_movement():\n    options = [\n        (0, -JOYSTICK_RADIUS),\n        (0, JOYSTICK_RADIUS),\n        (-JOYSTICK_RADIUS, 0),\n        (JOYSTICK_RADIUS, 0),\n        normalize_move(JOYSTICK_RADIUS, -JOYSTICK_RADIUS),\n        normalize_move(-JOYSTICK_RADIUS, -JOYSTICK_RADIUS),\n        normalize_move(JOYSTICK_RADIUS, JOYSTICK_RADIUS),\n        normalize_move(-JOYSTICK_RADIUS, JOYSTICK_RADIUS),\n    ]\n    random.shuffle(options)\n    return first_unblocked(options, get_random_movement())\n\n\n# ═══════════════════════════════════════════════════════\n#  ARCHETYPE DETECTION\n# ═══════════════════════════════════════════════════════\n\ndef detect_archetype():\n    ar = float(brawler_info.get("attack_range", attack_range or 400))\n    sr = float(brawler_info.get("safe_range", safe_range or 200))\n    wall_ignore = brawler_info.get("ignore_walls_for_attacks", False)\n\n    if wall_ignore:\n        return "LOBS"\n    if ar <= 256:\n        return "ASSASSIN"\n    if sr == 0.0 and ar <= 350:\n        return "TANK"\n    if ar >= 600:\n        return "SNIPER"\n    return "RANGED"\n\narchetype = detect_archetype()\n\n\n# ═══════════════════════════════════════════════════════\n#  ATTACK HELPERS\n# ═══════════════════════════════════════════════════════\n\ndef do_attack():\n    if not must_hold:\n        attack()\n        return\n\n    hold_attack_time = float(brawler_info.get("hold_attack", 0.0))\n\n    if persistent_data["time_since_holding_attack"] is None:\n        persistent_data["time_since_holding_attack"] = time.time()\n        attack(touch_up=False, touch_down=True)\n\n    elif time.time() - persistent_data["time_since_holding_attack"] >= hold_attack_time:\n        attack(touch_up=True, touch_down=False)\n        persistent_data["time_since_holding_attack"] = None\n\ndef try_use_super(enemy_coords, enemy_distance):\n    if not is_super_ready:\n        return\n\n    if persistent_data["time_since_holding_attack"] is not None:\n        return\n\n    super_type = brawler_info.get("super_type", "damage")\n    enemy_hittable = is_enemy_hittable(player_pos, enemy_coords, walls, "super")\n\n    should_super = (\n        enemy_hittable and (\n            enemy_distance <= super_range\n            or super_type in ["spawnable", "other"]\n            or (\n                _brawler_name in ["stu", "surge"]\n                and super_type == "charge"\n                and enemy_distance <= super_range + attack_range\n            )\n        )\n    )\n\n    if should_super:\n        if is_hypercharge_ready:\n            use_hypercharge()\n        use_super()\n\ndef try_attack(enemy_coords, enemy_distance, allow_wall_attack=False):\n    if enemy_distance > attack_range:\n        return False\n\n    enemy_hittable = is_enemy_hittable(player_pos, enemy_coords, walls, "attack")\n\n    if enemy_hittable or allow_wall_attack:\n        if is_gadget_ready and persistent_data["time_since_holding_attack"] is None:\n            if time.time() - persistent_data["last_gadget_use"] > 3.0:\n                use_gadget()\n                persistent_data["last_gadget_use"] = time.time()\n\n        do_attack()\n        return True\n\n    return False\n\n\n# ═══════════════════════════════════════════════════════\n#  HOLD ATTACK AUTO-RELEASE\n# ═══════════════════════════════════════════════════════\n\nif must_hold and persistent_data["time_since_holding_attack"] is not None:\n    hold_limit = float(brawler_info.get("hold_attack", 0.0)) + seconds_to_hold_attack_after_reaching_max\n    if time.time() - persistent_data["time_since_holding_attack"] >= hold_limit:\n        attack(touch_up=True, touch_down=False)\n        persistent_data["time_since_holding_attack"] = None\n\n\n# ═══════════════════════════════════════════════════════\n#  POISON GAS\n# ═══════════════════════════════════════════════════════\n\ndef avoid_poison_gas():\n    poison_gas = is_there_poison_gas(player_data)\n    x = 0\n    y = 0\n\n    if poison_gas["up"] or poison_gas["down"]:\n        if poison_gas["up"] > poison_gas["down"]:\n            y = JOYSTICK_RADIUS\n        else:\n            y = -JOYSTICK_RADIUS\n\n    if poison_gas["left"] or poison_gas["right"]:\n        if poison_gas["left"] > poison_gas["right"]:\n            x = JOYSTICK_RADIUS\n        else:\n            x = -JOYSTICK_RADIUS\n\n    if x == 0 and y == 0:\n        return None\n\n    move = normalize_move(x, y)\n    return first_unblocked([move, (x, 0), (0, y)], move)\n\n\n# ═══════════════════════════════════════════════════════\n#  NO ENEMY / EXPLORATION\n# ═══════════════════════════════════════════════════════\n\ndef no_enemy_movement():\n    closest_teammate_coords, teammate_distance = find_closest_teammate(\n        teammate_data, player_pos, walls\n    )\n\n    if closest_teammate_coords is not None:\n        if teammate_distance is None or teammate_distance > TILE_SIZE * 3:\n            return move_toward(closest_teammate_coords)\n\n    forward = (0, -JOYSTICK_RADIUS)\n    if not is_blocked(forward):\n        return forward\n\n    return random_safe_movement()\n\n\n# ═══════════════════════════════════════════════════════\n#  MAIN BEHAVIOR TREE \n# ═══════════════════════════════════════════════════════\n\nenemy_coords = None\nenemy_distance = None\n\n# 1. Detectar ameaças e alvos\nif is_there_enemy(enemy_data):\n    enemy_coords, enemy_distance = find_closest_enemy(\n        enemy_data, player_pos, walls, "attack"\n    )\n\nanti_gas_movement = avoid_poison_gas()\n\n# 2. Reação de Fuga do Gás\nif anti_gas_movement is not None:\n    movement = anti_gas_movement\n    \n    # Continua atirando mesmo fugindo do gás se houver inimigos\n    if enemy_coords is not None:\n        try_use_super(enemy_coords, enemy_distance)\n        if archetype == "LOBS":\n            try_attack(enemy_coords, enemy_distance, allow_wall_attack=True)\n        else:\n            try_attack(enemy_coords, enemy_distance)\n\n# 3. Árvore de Combate Padrão\nelse:\n    if enemy_coords is None:\n        movement = no_enemy_movement()\n    else:\n        try_use_super(enemy_coords, enemy_distance)\n        \n        # Ataca SEMPRE que estiver em alcance e com visão, independente do movimento\n        if archetype == "LOBS":\n            try_attack(enemy_coords, enemy_distance, allow_wall_attack=True)\n        else:\n            try_attack(enemy_coords, enemy_distance)\n\n        # ═══════════════════════════════════════════════\n        #  MOVIMENTAÇÃO POR ARQUÉTIPO (Sem travar ataque)\n        # ═══════════════════════════════════════════════\n        if archetype == "ASSASSIN":\n            if enemy_distance > attack_range * 0.40:\n                movement = move_toward(enemy_coords)\n            else:\n                movement = strafe_around(enemy_coords)\n\n        elif archetype == "TANK":\n            if enemy_distance > attack_range * 0.25:\n                movement = move_toward(enemy_coords)\n            else:\n                movement = strafe_around(enemy_coords)\n\n        elif archetype == "SNIPER":\n            min_safe = attack_range * 0.35\n            ideal_far = attack_range * 0.75\n\n            if enemy_distance < min_safe:\n                movement = move_away_from(enemy_coords)\n            elif enemy_distance <= ideal_far:\n                movement = strafe_around(enemy_coords)\n            else:\n                movement = move_toward(enemy_coords)\n\n        elif archetype == "LOBS":\n            ideal_dist = attack_range * 0.55\n\n            if enemy_distance < attack_range * 0.45:\n                movement = move_away_from(enemy_coords)\n            elif enemy_distance > ideal_dist:\n                movement = move_toward(enemy_coords)\n            else:\n                movement = strafe_around(enemy_coords)\n\n        else: # RANGED\n            min_safe = max(safe_range * 0.50, attack_range * 0.30)\n            ideal_far = attack_range * 0.60\n\n            if enemy_distance < min_safe:\n                movement = move_away_from(enemy_coords)\n            elif enemy_distance <= ideal_far:\n                movement = strafe_around(enemy_coords)\n            else:\n                movement = move_toward(enemy_coords)\n\n        # Tratamento contra paredes quando em combate\n        if is_blocked(movement):\n            if enemy_distance < safe_range:\n                movement = first_unblocked(\n                    [move_away_from(enemy_coords), strafe_around(enemy_coords), random_safe_movement()], movement\n                )\n            else:\n                movement = first_unblocked(\n                    [move_toward(enemy_coords), strafe_around(enemy_coords), random_safe_movement()], movement\n                )\n\n\n# ═══════════════════════════════════════════════════════\n#  FINAL SAFETY\n# ═══════════════════════════════════════════════════════\n\nif movement is None:\n    movement = (0, 0)\n\nif is_path_blocked(player_data, movement, walls):\n    movement = random_safe_movement()\n', 'survivor.xlambot': '{"name": "Survivor", "description": "Держится с командой, избегает газа и играет на выживание.", "brawlers": ["all"], "gamemodes": ["trio showdown"], "author": "xlamBOT", "date": "2026-10-06"}\ndef no_enemy_movement():\n    player_pos = get_entity_pos(player_data)\n    closest_teammate_coords, dist = find_closest_teammate(teammate_data, player_pos, walls)\n\n    if not closest_teammate_coords:\n        # Calculate vector to the center of the screen\n        center_x = 1920*width_ratio / 2\n        center_y = 1080*height_ratio / 2\n\n        dx = center_x - player_pos[0]\n        dy = center_y - player_pos[1]\n        dist_to_center = math.hypot(dx, dy)\n\n        # If close to center, randomly offset the TARGET coordinate instead\n        if dist_to_center < TILE_SIZE * 2:\n            # TILE_SIZE is scaled and therefore a float, and randint refuses\n            # floats, so the jitter has to be rounded to whole pixels first.\n            jitter_x = random.randint(int(-TILE_SIZE), int(TILE_SIZE))\n            jitter_y = random.randint(int(-TILE_SIZE), int(TILE_SIZE))\n            center_x += jitter_x\n            center_y += jitter_y\n            dx = center_x - player_pos[0]\n            dy = center_y - player_pos[1]\n            dist_to_center = math.hypot(dx, dy)\n\n        if dist_to_center > 0:\n            direction_x, direction_y = dx, dy\n        else:\n            direction_x, direction_y = 0.0, 0.0\n\n        movement_options = [(direction_x, direction_y), (direction_x, 0), (0, direction_y)]\n\n        for move in movement_options:\n            if not is_path_blocked(player_data, move, walls):\n                return move\n        return movement_options[0]\n    if dist < TILE_SIZE:\n        alternative_moves = [\n            (0, -JOYSTICK_RADIUS), (-JOYSTICK_RADIUS, 0),\n            (0, JOYSTICK_RADIUS), (JOYSTICK_RADIUS, 0)\n        ]\n        return random.choice(alternative_moves)\n\n    dx = closest_teammate_coords[0] - player_pos[0]\n    dy = closest_teammate_coords[1] - player_pos[1]\n\n    direction_x, direction_y = dx, dy\n    movement_options = [(direction_x, direction_y), (direction_x, 0), (0, direction_y)]\n\n    for move in movement_options:\n        if not is_path_blocked(player_data, move, walls):\n            return move\n    else:\n        return movement_options[0]\n\ndef avoid_poison_gas():\n    opposite_direction = {"up": JOYSTICK_RADIUS, "down": -JOYSTICK_RADIUS, "left": JOYSTICK_RADIUS, "right": -JOYSTICK_RADIUS}\n    poison_gas = is_there_poison_gas(player_data)\n    x, y = 0, 0\n    if poison_gas["up"] or poison_gas["down"]:\n        if poison_gas["up"] > poison_gas["down"]:\n            y = opposite_direction["up"]\n        else:\n            y = opposite_direction["down"]\n    if poison_gas["left"] or poison_gas["right"]:\n        if poison_gas["left"] > poison_gas["right"]:\n            x = opposite_direction["left"]\n        else:\n            x = opposite_direction["right"]\n\n    return (x, y) if x != 0 or y != 0 else None\n\ndef living_teammates():\n    """How many teammates are still up.\n\n    At high power a fight is only worth taking with your team next to you. When\n    the team is down, every duel is a 1v3, and in Showdown dying is what costs\n    trophies, so the bot stops looking for fights and just stays alive.\n    """\n    return len(teammate_data) if teammate_data else 0\n\ndef keep_away_from_enemy(player_pos, enemy_coords):\n    """Step off the line to the enemy, preferring a direction that is open.\n\n    Backing straight up often means backing into a wall, which turns a retreat\n    into a corner fight, so the sideways options are tried first.\n    """\n    dx = player_pos[0] - enemy_coords[0]\n    dy = player_pos[1] - enemy_coords[1]\n    length = math.hypot(dx, dy)\n    if length <= 0:\n        dx, dy, length = 0.0, 1.0, 1.0\n    options = [\n        (dx, dy),\n        (-dy, dx),\n        (dy, -dx),\n        (0, -JOYSTICK_RADIUS if dy < 0 else JOYSTICK_RADIUS),\n        (-JOYSTICK_RADIUS if dx < 0 else JOYSTICK_RADIUS, 0),\n    ]\n    for move in options:\n        if not is_path_blocked(player_data, move, walls):\n            return move\n    return options[0]\n\ndef find_brawler_info(name):\n    """Look the brawler up, tolerating a different spelling in the table.\n\n    Some entries are keyed differently from how they are written in the queue\n    (Jess is stored as "jessie"), and the playstyle sandbox has no builtins, so\n    raising here would not even produce a readable error.\n    """\n    table = brawlers_info\n    if name in table:\n        return table[name]\n    lowered = str(name).lower()\n    for key, info in table.items():\n        if str(key).lower() == lowered:\n            return info\n    for key, info in table.items():\n        base = str(key).lower()\n        if base.startswith(lowered) or lowered.startswith(base):\n            return info\n    return None\n\nbrawler_info = find_brawler_info(brawler)\nif not brawler_info:\n    brawler_info = {"hold_attack": 0.0, "super_type": "other", "attack_range": 0,\n                    "safe_range": 0, "super_range": 0}\nmust_brawler_hold_attack = must_brawler_hold_attack(brawler, brawlers_info)\n# if a brawler has been holding an attack for its max duration + the bot setting, then we release\nif must_brawler_hold_attack and persistent_data["time_since_holding_attack"] is not None and time.time() - persistent_data["time_since_holding_attack"] >= brawler_info[\'hold_attack\'] + seconds_to_hold_attack_after_reaching_max:\n    attack(touch_up=True, touch_down=False)\n    persistent_data["time_since_holding_attack"] = None\n\nsafe_range, attack_range, super_range = get_brawler_range(brawler)\nplayer_pos = get_entity_pos(player_data)\n#if debug: print("found player pos:", player_pos)\nanti_poison_gas_movement = avoid_poison_gas()\nif anti_poison_gas_movement:\n    movement = anti_poison_gas_movement\nif not is_there_enemy(enemy_data):\n    if not anti_poison_gas_movement:\n        movement = no_enemy_movement()\nelse:\n    enemy_coords, enemy_distance = find_closest_enemy(enemy_data, player_pos, walls, "attack")\n    if enemy_coords is None:\n        if not anti_poison_gas_movement:\n            movement = no_enemy_movement()\n    else:\n        #if debug: print("found enemy pos:", enemy_coords)\n        # Chasing is what puts the bot into gas and into 1v2s. Only close the gap\n        # when the team is together and the target is already close by.\n        chase_leash = TILE_SIZE * 6\n        team_up = living_teammates() >= 2\n        # A brawl match moves trophies by tens, so the honest reading of a rule\n        # like this needs about 1000 matches per arm to tell a 6-point change\n        # apart from noise - some 86 hours of play. Measured over 84 matches the\n        # gap was 64% vs 61% top-2 with p = 0.65, which is nothing. So the ring\n        # gate is not here: an unmeasurable rule is not worth carrying into every\n        # match. Contact stays allowed when the team is together and the target\n        # is close, as before.\n        may_close_in = team_up and enemy_distance <= chase_leash\n\n        if not anti_poison_gas_movement:\n            if may_close_in and enemy_distance > safe_range:\n                direction_x = enemy_coords[0] - player_pos[0]\n                direction_y = enemy_coords[1] - player_pos[1]\n                movement_options = [(direction_x, direction_y), (direction_x, 0), (0, direction_y)]\n            else:\n                # Either the target is too far to be worth walking to, or the\n                # team is gone and a duel would be suicide. Open the distance and\n                # let the enemy come to us.\n                #\n                # Prefer the middle over stepping away from this particular\n                # enemy: gas damage grows with distance from the centre, so the\n                # centre is both the safe spot and the one a respawned teammate\n                # can defend.\n                movement_options = [\n                    no_enemy_movement(),\n                    keep_away_from_enemy(player_pos, enemy_coords),\n                ]\n\n            for move in movement_options:\n                if not is_path_blocked(player_data, move, walls):\n                    movement = move\n                    break\n            else:\n                alternative_moves = [(0, -JOYSTICK_RADIUS), (-JOYSTICK_RADIUS, 0), (0, JOYSTICK_RADIUS), (JOYSTICK_RADIUS, 0)]\n                random.shuffle(alternative_moves)\n                for move in alternative_moves:\n                    if not is_path_blocked(player_data, move, walls):\n                        movement = move\n                        break\n                else:\n                    movement = movement_options[0]\n\n        if is_super_ready and persistent_data["time_since_holding_attack"] is None:\n            super_type = brawler_info[\'super_type\']\n            enemy_hittable = is_enemy_hittable(player_pos, enemy_coords, walls, "super")\n\n            # Held back unless the target is inside super range: dumping the\n            # super on the first brawler that shows up is how the bot ends up\n            # defenceless for the fight that actually decides the placement.\n            worth_spending = enemy_distance <= super_range or super_type in ["spawnable", "other"]\n            if (enemy_hittable and worth_spending and\n                    (enemy_distance <= super_range\n                     or super_type in ["spawnable", "other"]\n                     or (brawler in ["stu", "surge"] and super_type == "charge" and enemy_distance <= super_range + attack_range)\n                    )):\n                if is_hypercharge_ready:\n                    use_hypercharge()\n\n                use_super()\n\n        # Attack if enemy is within attack range and hittable\n        if enemy_distance <= attack_range:\n            enemy_hittable = is_enemy_hittable(player_pos, enemy_coords, walls, "attack")\n            if enemy_hittable:\n                if is_gadget_ready and persistent_data["time_since_holding_attack"] is None:\n                    use_gadget()\n\n                if not must_brawler_hold_attack:\n                    attack()\n                else:\n                    if persistent_data["time_since_holding_attack"] is None:\n                        persistent_data["time_since_holding_attack"] = time.time()\n                        attack(touch_up=False, touch_down=True)\n                    elif time.time() - persistent_data["time_since_holding_attack"] >= brawlers_info[brawler][\'hold_attack\']:\n                        attack(touch_up=True, touch_down=False)\n                        persistent_data["time_since_holding_attack"] = None\n'}

ALIASES = {
    "universal_smart_v5_slarckvul_eddition.xlambot": "aggressive.xlambot",
    "showdown_survivor.xlambot": "survivor.xlambot",
    "team_showdown.xlambot": "survivor.xlambot",
    "default_right.xlambot": "survivor.xlambot",
    "default_up.xlambot": "survivor.xlambot",
    "follower.xlambot": "survivor.xlambot",
    "heist_guard.xlambot": "survivor.xlambot",
}

def canonical_playstyle(filename):
    name = str(filename or "").strip().lower()
    return ALIASES.get(name, name if name in BUILT_IN_PLAYSTYLES else "survivor.xlambot")
